from PIL import Image
import sys, math

def load(p):
    im = Image.open(p).convert('L')
    return im.load(), im.size[0], im.size[1]

def centroid_bright(path, thresh=215):
    px,W,H = load(path)
    # connected components of bright pixels
    seen = bytearray(W*H)
    best=None
    for y in range(H):
        for x in range(W):
            i=y*W+x
            if seen[i] or px[x,y]<thresh: continue
            # BFS
            stack=[(x,y)]; seen[i]=1; pts=[]
            while stack:
                cx,cy=stack.pop(); pts.append((cx,cy))
                for nx,ny in ((cx+1,cy),(cx-1,cy),(cx,cy+1),(cx,cy-1)):
                    if 0<=nx<W and 0<=ny<H:
                        j=ny*W+nx
                        if not seen[j] and px[nx,ny]>=thresh:
                            seen[j]=1; stack.append((nx,ny))
            if best is None or len(pts)>len(best): best=pts
    if not best: return None
    n=len(best)
    sx=sum(p[0] for p in best); sy=sum(p[1] for p in best)
    xs=[p[0] for p in best]; ys=[p[1] for p in best]
    return (sx/n, sy/n, n, min(xs),max(xs),min(ys),max(ys))

def centroid_dark_components(path, thresh=90, amin=80, amax=4000):
    px,W,H = load(path)
    seen = bytearray(W*H)
    comps=[]
    for y in range(H):
        for x in range(W):
            i=y*W+x
            if seen[i] or px[x,y]>=thresh: continue
            stack=[(x,y)]; seen[i]=1; pts=[]
            touches_edge=False
            while stack:
                cx,cy=stack.pop(); pts.append((cx,cy))
                if cx==0 or cy==0 or cx==W-1 or cy==H-1: touches_edge=True
                for nx,ny in ((cx+1,cy),(cx-1,cy),(cx,cy+1),(cx,cy-1)):
                    if 0<=nx<W and 0<=ny<H:
                        j=ny*W+nx
                        if not seen[j] and px[nx,ny]<thresh:
                            seen[j]=1; stack.append((nx,ny))
            n=len(pts)
            if amin<=n<=amax and not touches_edge:
                sx=sum(p[0] for p in pts); sy=sum(p[1] for p in pts)
                xs=[p[0] for p in pts]; ys=[p[1] for p in pts]
                comps.append((sx/n, sy/n, n, min(xs),max(xs),min(ys),max(ys)))
    return comps

if __name__=='__main__':
    mode=sys.argv[1]
    if mode=='pin':
        for f in sys.argv[2:]:
            print(f, centroid_bright(f))
    else:
        for f in sys.argv[2:]:
            print(f)
            for c in centroid_dark_components(f):
                print('  bore cand: cx=%.2f cy=%.2f area=%d x[%d,%d] y[%d,%d]'%c)
